<template><div class="p-2 app-container"><el-card shadow="never"><template #header><div class="header"><div><h3>余额流水</h3><p>充值、功能消费和失败退款均记录在这里。</p></div><el-button icon="Refresh" @click="load">刷新</el-button></div></template><el-table v-loading="loading" :data="rows" border><el-table-column prop="email" label="用户邮箱" min-width="180"/><el-table-column prop="source" label="来源" width="100"/><el-table-column prop="remark" label="说明"/><el-table-column prop="order_no" label="关联单号" min-width="210"/><el-table-column label="余额变动" width="110"><template #default="scope"><b :class="scope.row.change_amount>0?'plus':'minus'">{{scope.row.change_amount>0?'+':''}}{{scope.row.change_amount}}</b></template></el-table-column><el-table-column prop="balance" label="变动后余额" width="110"/><el-table-column prop="create_time" label="时间" min-width="170"/></el-table></el-card></div></template>
